const W="opening-160-rows", R="row";
const names=["instructions","packets","stackLoads","stackStores"];
const out={};
for (const arm of ["typed-stock","typed-scalar","typed-pie"]) {
  const a = profiles.arm(arm).region(R).workload(W);
  const row={};
  for (const n of names) {
    const r = q.run(a.total(n));
    row[n] = (r && r.status!==undefined) ? {v:r.value, s:r.status, u:r.unit} : r;
  }
  out[arm]=row;
}
// derived
for (const arm of Object.keys(out)) {
  const o=out[arm], I=o.instructions.v, L=o.stackLoads.v, S=o.stackStores.v, P=o.packets.v;
  out[arm].derived = {
    stackAccesses: L+S,
    stackAccessPctOfInstructions: +(100*(L+S)/I).toFixed(3),
    loadsPctOfInstructions: +(100*L/I).toFixed(3),
    storesPctOfInstructions: +(100*S/I).toFixed(3),
    packetsPctOfInstructions: +(100*P/I).toFixed(3)
  };
}
JSON.stringify(out)

const sc = profiles.arm("typed-scalar").describe();
const pie = profiles.arm("typed-pie").describe();
let hw; try { hw = hardware.help(); } catch(e){ hw = "ERR "+e.message; }
const samples = profiles.arm("typed-stock").region("row").workload("opening-160-rows").samples();
JSON.stringify({
  scalar: {treatment: sc.treatment, notA: sc.notA, cannotAttribute: sc.cannotAttribute},
  pieNotA: pie.notA,
  hw: (typeof hw==="string"? hw.slice(0,900) : JSON.stringify(hw).slice(0,900)),
  samples: samples
})

const W="opening-160-rows", R="row";
const get=(arm,n)=>q.run(profiles.arm(arm).region(R).workload(W).total(n)).value;
const deltas={};
for (const [b,c] of [["typed-stock","typed-scalar"],["typed-stock","typed-pie"],["typed-scalar","typed-pie"]]) {
  const d={};
  for (const n of ["instructions","stackLoads","stackStores"]) {
    const B=get(b,n), C=get(c,n);
    d[n]={base:B,cand:C,delta:C-B,pct:+(((C-B)/B)*100).toFixed(3)};
  }
  const Bs=get(b,"stackLoads")+get(b,"stackStores"), Cs=get(c,"stackLoads")+get(c,"stackStores");
  d.stackAccesses={base:Bs,cand:Cs,delta:Cs-Bs,pct:+(((Cs-Bs)/Bs)*100).toFixed(3)};
  deltas[b+" -> "+c]=d;
}
const meta = hardware.metadata();
const pieP = hardware.pairs('stock','pie','primary');
JSON.stringify({deltas, hwMeta: meta, piePairs: pieP.slice(0,4), piePairCount: pieP.length})

const g2=(arm,n)=>q.run(profiles.arm(arm).region("row").workload("opening-160-rows").total(n)).value;
const d2={};
for (const [b,c] of [["typed-stock","typed-scalar"],["typed-stock","typed-pie"],["typed-scalar","typed-pie"]]) {
  const d={};
  for (const n of ["instructions","stackLoads","stackStores"]) {
    const B=g2(b,n), C=g2(c,n);
    d[n]={base:B,cand:C,delta:C-B,pct:+(((C-B)/B)*100).toFixed(3)};
  }
  const Bs=g2(b,"stackLoads")+g2(b,"stackStores"), Cs=g2(c,"stackLoads")+g2(c,"stackStores");
  d.stackAccesses={base:Bs,cand:Cs,delta:Cs-Bs,pct:+(((Cs-Bs)/Bs)*100).toFixed(3)};
  d2[b+" -> "+c]=d;
}
let meta2, piePairs;
try { meta2 = hardware.metadata(); piePairs = hardware.pairs('stock','pie','primary'); } catch(e){ meta2 = "ERR "+e.message; }
JSON.stringify({d2, hwMeta: typeof meta2==="string"?meta2:meta2, piePairCount: piePairs?piePairs.length:null, piePairs: piePairs?piePairs.slice(0,4):null})

const stat=(arr)=>{const v=arr.slice().sort((a,b)=>a-b);const med=v[Math.floor(v.length/2)];return {n:v.length,min:+v[0].toFixed(3),median:+med.toFixed(3),max:+v[v.length-1].toFixed(3)};};
const scP = hardware.pairs('stock','scalar','primary');
const piP = hardware.pairs('stock','pie','primary');
const crcAgree=(ps)=>ps.every(p=>p.outputCRC && new Set(p.outputCRC).size===1);
JSON.stringify({
  stock_scalar: {savedPct: stat(scP.map(p=>p.savedPct)), crcAllSameAcrossPoses: crcAgree(scP), poses:[...new Set(scP.map(p=>p.pose))]},
  stock_pie: {savedPct: stat(piP.map(p=>p.savedPct)), crcAllSameAcrossPoses: crcAgree(piP), poses:[...new Set(piP.map(p=>p.pose))]},
  instrPct: {stock_scalar:-11.328, stock_pie:-13.225},
  stackPct: {stock_scalar:-19.451, stock_pie:-19.438}
})

const all = [...hardware.pairs('stock','scalar','primary'), ...hardware.pairs('stock','pie','primary')];
const byPose = {};
for (const p of all) { (byPose[p.pose] ||= new Set()).add(p.outputCRC.join(",")); }
const poseCrc = Object.fromEntries(Object.entries(byPose).map(([k,v])=>[k,{distinctCRCTriples:v.size, distinctSingleCRCs:new Set([...v].flatMap(s=>s.split(","))).size}]));
const withinPairDistinct = all.every(p=>new Set(p.outputCRC).size===3);
const caps = q.help("capabilities");
JSON.stringify({poseCrc, withinPairDistinct, capsTail: (typeof caps==="string"?caps:JSON.stringify(caps)).slice(0,1400)})

let capsAll; try { capsAll = q.capabilities(); } catch(e){ capsAll = "ERR "+e.message; }
const capList = Array.isArray(capsAll)? capsAll : (capsAll && capsAll.capabilities ? capsAll.capabilities : capsAll);
const unavail = Array.isArray(capList)? capList.filter(c=>/unavail|absent|unsupported/.test(JSON.stringify(c.status))) : null;
const ratio = (name, dI, dA) => ({pair:name, instrSaved:-dI, stackAccessesSaved:-dA, instrPerStackAccess:+((-dI)/(-dA)).toFixed(3)});
JSON.stringify({
  capCount: Array.isArray(capList)?capList.length:null,
  unavailCount: unavail?unavail.length:null,
  unavail: unavail? unavail.slice(0,10) : String(JSON.stringify(capList)).slice(0,900),
  exchangeRate: [ ratio("stock->scalar", -408787, -250942), ratio("stock->pie", -477262, -250777) ]
})

const sm = profiles.arm("typed-stock").region("row").workload("opening-160-rows").samples();
const perRow = Object.entries(sm).map(([k,v])=>({row:+k, instr:v.instructions, spAccess:v.stackLoads+v.stackStores, sharePct:+((100*(v.stackLoads+v.stackStores)/v.instructions).toFixed(2))}));
JSON.stringify({perRow, sampleCount: Object.keys(sm).length, workloadRows: 160, meanInstrPerRow: +(3608697/160).toFixed(1), aggSharePct: 35.75})
